package vn.edu.eaut.lab9.controller;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import vn.edu.eaut.lab9.model.*;import vn.edu.eaut.lab9.service.*;import java.io.*;import java.time.*;
@WebServlet("/sinh-vien") public class SinhVienController extends HttpServlet{private final SinhVienService s=new SinhVienService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{String a=r.getParameter("action");if("delete".equals(a)){s.delete(Integer.parseInt(r.getParameter("id")));r.getSession().setAttribute("msg","Đã xóa sinh viên");p.sendRedirect("sinh-vien");return;}if("edit".equals(a)){r.setAttribute("sv",s.find(Integer.parseInt(r.getParameter("id"))));r.setAttribute("classes",s.classes());r.getRequestDispatcher("/views/sinhvien/form.jsp").forward(r,p);return;}if("add".equals(a)){r.setAttribute("classes",s.classes());r.getRequestDispatcher("/views/sinhvien/form.jsp").forward(r,p);return;}String q=r.getParameter("keyword");int page=Math.max(0,Integer.parseInt(r.getParameter("page")==null?"0":r.getParameter("page")));r.setAttribute("dsSinhVien",s.list(q,page));r.setAttribute("pages",s.pages(q));r.setAttribute("page",page);r.setAttribute("keyword",q==null?"":q);r.getRequestDispatcher("/views/sinhvien/list.jsp").forward(r,p);}catch(Exception e){r.setAttribute("error",e.getMessage());r.getRequestDispatcher("/index.jsp").forward(r,p);}}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{try{String id=r.getParameter("id"),lop=r.getParameter("lopHocId");SinhVien sv=id==null||id.isBlank()?new SinhVien():s.find(Integer.parseInt(id));sv.setMaSinhVien(r.getParameter("maSinhVien"));sv.setHoTen(r.getParameter("hoTen"));sv.setEmail(r.getParameter("email"));sv.setLopHoc(new vn.edu.eaut.lab9.repository.LopHocRepository().findById(Integer.parseInt(lop)));String ns=r.getParameter("ngaySinh");sv.setNgaySinh(ns==null||ns.isBlank()?null:LocalDate.parse(ns));if(id==null||id.isBlank())s.save(sv);else s.update(sv);r.getSession().setAttribute("msg","Lưu sinh viên thành công");p.sendRedirect("sinh-vien");}catch(Exception e){p.sendRedirect("sinh-vien?error="+java.net.URLEncoder.encode(e.getMessage(),"UTF-8"));}}}
